create table if not exists instruments(id uuid primary key default gen_random_uuid(),symbol text not null,exchange text not null,company_name text,market_cap_bucket text,sector text,created_at timestamptz default now(),unique(symbol,exchange));
create table if not exists market_pulses(id uuid primary key default gen_random_uuid(),pulse_type text not null,entity_key text not null,score numeric(5,2) not null,state text not null,change numeric(8,2),factors jsonb default '{}',calculated_at timestamptz default now());
create index if not exists market_pulses_lookup on market_pulses(pulse_type,entity_key,calculated_at desc);
create table if not exists news_articles(id uuid primary key default gen_random_uuid(),source text not null,url text,title text not null,summary text,published_at timestamptz,sentiment_score numeric(6,2),impact_score numeric(6,2),entities jsonb default '[]',created_at timestamptz default now());
create table if not exists stock_scores(id uuid primary key default gen_random_uuid(),instrument_id uuid references instruments(id),total_score numeric(5,2) not null,factor_scores jsonb default '{}',expected_return_low numeric(8,2),expected_return_high numeric(8,2),confidence numeric(5,2),score_version text not null,calculated_at timestamptz default now());
